import{_ as o,I as a,o as i,c as s,b6 as d,J as r}from"./chunks/framework.BUXTSoD9.js";const u=JSON.parse('{"title":"資料視覺化與儀表板","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/appendix/5-data/data-visualization.md","filePath":"zh-tw/appendix/5-data/data-visualization.md"}'),n={name:"zh-tw/appendix/5-data/data-visualization.md"};function h(b,t,g,c,p,_){const l=a("ChartTypeSelectorDemo"),e=a("DashboardLayoutDemo");return i(),s("div",null,[t[0]||(t[0]=d('<h1 id="資料視覺化與儀表板" tabindex="-1">資料視覺化與儀表板 <a class="header-anchor" href="#資料視覺化與儀表板" aria-label="Permalink to “資料視覺化與儀表板”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>一張好的圖表勝過一千行資料。</strong> 資料視覺化是將抽象的數字轉化為直觀的視覺表達，讓人能在幾秒內理解數據背後的故事。從 Excel 圖表到 Grafana 監控大螢幕，視覺化無處不在。</p></div><p><strong>這篇文章會帶你學什麼？</strong></p><p>學完這章後，你將獲得：</p><ul><li><strong>圖表選擇</strong>：根據資料目的選擇最合適的圖表類型</li><li><strong>視覺化原則</strong>：掌握資料視覺化的核心設計原則</li><li><strong>儀表板設計</strong>：了解不同類型儀表板的佈局模式</li><li><strong>工具生態</strong>：熟悉主流視覺化工具的定位和選型</li><li><strong>常見陷阱</strong>：避免誤導性圖表和常見的視覺化錯誤</li></ul><table tabindex="0"><thead><tr><th>章節</th><th>內容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>圖表類型選擇</td><td>比較、趨勢、佔比、分佈、關係</td></tr><tr><td><strong>第 2 章</strong></td><td>視覺化設計原則</td><td>資料墨水比、一致性、可讀性</td></tr><tr><td><strong>第 3 章</strong></td><td>儀表板佈局</td><td>概覽型、對比型、下鑽型、即時型</td></tr><tr><td><strong>第 4 章</strong></td><td>工具選型</td><td>ECharts、D3、Grafana、Metabase</td></tr><tr><td><strong>第 5 章</strong></td><td>常見陷阱</td><td>截斷座標軸、3D 圓餅圖、顏色濫用</td></tr></tbody></table><hr><h2 id="_0-全景圖-為什麼需要視覺化" tabindex="-1">0. 全景圖：為什麼需要視覺化？ <a class="header-anchor" href="#_0-全景圖-為什麼需要視覺化" aria-label="Permalink to “0. 全景圖：為什麼需要視覺化？”">​</a></h2><p>人類大腦處理視覺資訊的速度比處理文字快得多。一張折線圖能讓你很快看出「上個月銷售額在下降」，而同樣的資訊如果用表格呈現，你可能需要逐行對比才能得出結論。</p><p>視覺化的核心價值：</p><ul><li><strong>發現模式</strong>：趨勢、週期、異常值在圖表中一目了然</li><li><strong>輔助決策</strong>：讓非技術人員也能理解資料，參與決策</li><li><strong>溝通效率</strong>：一圖勝千言，減少資料解讀的歧義</li></ul><div class="tip custom-block"><p class="custom-block-title">視覺化 ≠ 好看</p><p>視覺化的目標是<strong>傳達資訊</strong>，不是炫技。一個樸素但準確的長條圖，遠比一個花俏但難以理解的 3D 圖表更有價值。</p></div><hr><h2 id="_1-圖表類型選擇-用對圖表講對故事" tabindex="-1">1. 圖表類型選擇：用對圖表講對故事 <a class="header-anchor" href="#_1-圖表類型選擇-用對圖表講對故事" aria-label="Permalink to “1. 圖表類型選擇：用對圖表講對故事”">​</a></h2><p>選擇圖表的第一步不是「我喜歡什麼圖表」，而是「我想傳達什麼資訊」。不同的資料目的對應不同的最佳圖表類型。</p>',15)),r(l),t[1]||(t[1]=d('<h3 id="圖表選擇速查表" tabindex="-1">圖表選擇速查表 <a class="header-anchor" href="#圖表選擇速查表" aria-label="Permalink to “圖表選擇速查表”">​</a></h3><table tabindex="0"><thead><tr><th>資料目的</th><th>推薦圖表</th><th>不推薦</th><th>原因</th></tr></thead><tbody><tr><td>比較大小</td><td>長條圖、橫條圖</td><td>圓餅圖</td><td>人眼對長度差異比角度差異更敏感</td></tr><tr><td>展示趨勢</td><td>折線圖、面積圖</td><td>長條圖</td><td>折線的連續性暗示時間的連續性</td></tr><tr><td>展示佔比</td><td>圓餅圖（≤5 類）、堆疊長條圖</td><td>3D 圓餅圖</td><td>3D 透視會扭曲面積比例</td></tr><tr><td>展示分佈</td><td>直方圖、盒鬚圖</td><td>折線圖</td><td>分佈需要看頻率，不是趨勢</td></tr><tr><td>展示關係</td><td>散佈圖、氣泡圖</td><td>長條圖</td><td>兩個連續變數的關係需要二維空間</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一個簡單的決策規則</p><ul><li><strong>一個變數</strong> → 直方圖（分佈）或數字卡片（KPI）</li><li><strong>兩個變數</strong> → 折線圖（時間 vs 數值）或散佈圖（數值 vs 數值）</li><li><strong>多個類別</strong> → 長條圖（比較）或圓餅圖（佔比，≤5 類）</li><li><strong>多維度</strong> → 雷達圖或平行座標圖</li></ul></div><hr><h2 id="_2-視覺化設計原則-讓資料說話" tabindex="-1">2. 視覺化設計原則：讓資料說話 <a class="header-anchor" href="#_2-視覺化設計原則-讓資料說話" aria-label="Permalink to “2. 視覺化設計原則：讓資料說話”">​</a></h2><p>好的視覺化不是「好看」，而是「好懂」。Edward Tufte 在《The Visual Display of Quantitative Information》中提出的幾個經典原則，至今仍是視覺化設計的重要參考。</p><table tabindex="0"><thead><tr><th>原則</th><th>說明</th><th>反面案例</th></tr></thead><tbody><tr><td>資料墨水比</td><td>圖表中用於展示資料的「墨水」佔比應盡量高</td><td>過多的網格線、裝飾性元素</td></tr><tr><td>最小化非資料元素</td><td>去除不傳達資訊的視覺元素</td><td>3D 效果、陰影、漸層背景</td></tr><tr><td>一致的比例尺</td><td>座標軸從零開始，刻度均勻；若截斷座標軸必須明確標註</td><td>Y 軸從 95 開始卻不說明</td></tr><tr><td>合理的顏色使用</td><td>用顏色編碼資訊，而非裝飾</td><td>彩虹色表示有序資料</td></tr><tr><td>清晰的標註</td><td>標題、軸標籤、圖例、單位缺一不可</td><td>沒有單位、沒有時間範圍</td></tr></tbody></table><h3 id="_2-1-資料墨水比-data-ink-ratio" tabindex="-1">2.1 資料墨水比（Data-Ink Ratio） <a class="header-anchor" href="#_2-1-資料墨水比-data-ink-ratio" aria-label="Permalink to “2.1 資料墨水比（Data-Ink Ratio）”">​</a></h3><blockquote><p>圖表中用於表達資料的「墨水」佔總「墨水」的比例應該盡可能高。</p></blockquote><p>簡單說：<strong>刪掉一切不傳達資訊的元素</strong>。</p><table tabindex="0"><thead><tr><th>應該刪掉的</th><th>應該保留的</th></tr></thead><tbody><tr><td>3D 效果、陰影、漸層</td><td>資料點、座標軸標籤</td></tr><tr><td>多餘的網格線</td><td>關鍵參考線（如目標值）</td></tr><tr><td>裝飾性圖示</td><td>圖例（當有多系列時）</td></tr><tr><td>花俏的背景色</td><td>清晰的標題和單位</td></tr></tbody></table><h3 id="_2-2-一致性原則" tabindex="-1">2.2 一致性原則 <a class="header-anchor" href="#_2-2-一致性原則" aria-label="Permalink to “2.2 一致性原則”">​</a></h3><ul><li><strong>顏色一致</strong>：同一個維度在不同圖表中用同一種顏色，如「收入」始終用藍色</li><li><strong>比例一致</strong>：座標軸盡量從 0 開始，除非有充分理由並且明確標註</li><li><strong>時間一致</strong>：時間軸的間隔應該均勻，不要把不等距時間點畫成等距</li></ul><h3 id="_2-3-可讀性原則" tabindex="-1">2.3 可讀性原則 <a class="header-anchor" href="#_2-3-可讀性原則" aria-label="Permalink to “2.3 可讀性原則”">​</a></h3><ul><li><strong>標題要說結論</strong>：不是「月度銷售額」，而是「銷售額連續 3 個月下降」</li><li><strong>標註關鍵點</strong>：在異常值、轉折點處加標註，引導讀者注意力</li><li><strong>控制資訊密度</strong>：一張圖表傳達 1-2 個核心資訊，不要塞太多</li></ul><div class="tip custom-block"><p class="custom-block-title">顏色使用的三條規則</p><ol><li><strong>同一指標用同一顏色</strong>：收入在所有圖表中都用藍色，不要一下藍一下綠</li><li><strong>有序資料用漸層色</strong>：溫度從低到高用藍→紅漸層，不要用離散色</li><li><strong>考慮色盲友善</strong>：約 8% 的男性有紅綠色盲，避免僅用紅綠區分關鍵資訊</li></ol></div><hr><h2 id="_3-儀表板佈局-不同場景-不同模式" tabindex="-1">3. 儀表板佈局：不同場景，不同模式 <a class="header-anchor" href="#_3-儀表板佈局-不同場景-不同模式" aria-label="Permalink to “3. 儀表板佈局：不同場景，不同模式”">​</a></h2><p>儀表板（Dashboard）是多個圖表的有機組合。好的儀表板不是把圖表堆在一起，而是根據使用場景選擇合適的佈局模式。</p>',19)),r(e),t[2]||(t[2]=d('<h3 id="四種常見佈局模式" tabindex="-1">四種常見佈局模式 <a class="header-anchor" href="#四種常見佈局模式" aria-label="Permalink to “四種常見佈局模式”">​</a></h3><table tabindex="0"><thead><tr><th>佈局模式</th><th>核心結構</th><th>適用場景</th><th>設計要點</th></tr></thead><tbody><tr><td>全局概覽型</td><td>KPI 卡片 + 趨勢圖 + 明細表</td><td>管理層日報、營運大盤</td><td>核心指標放最上方，一眼看到關鍵數字</td></tr><tr><td>對比分析型</td><td>左右對稱佈局</td><td>A/B 測試、同環比分析</td><td>保持對比維度一致，突出差異</td></tr><tr><td>下鑽分析型</td><td>從彙總到明細逐層展開</td><td>銷售分析、使用者行為分析</td><td>支援點擊互動，逐層深入</td></tr><tr><td>即時監控型</td><td>大數字 + 即時曲線 + 警報狀態</td><td>雙十一大螢幕、伺服器監控</td><td>自動重新整理，深色背景，適合投影</td></tr></tbody></table><h3 id="儀表板設計的-5-個原則" tabindex="-1">儀表板設計的 5 個原則 <a class="header-anchor" href="#儀表板設計的-5-個原則" aria-label="Permalink to “儀表板設計的 5 個原則”">​</a></h3><ol><li><strong>先問「誰在看」</strong>：CEO 看戰略指標，營運看過程指標，工程師看技術指標</li><li><strong>5 秒規則</strong>：使用者應該在 5 秒內理解儀表板的核心資訊</li><li><strong>資訊層次</strong>：最重要的放左上角，次要的放下方</li><li><strong>減少捲動</strong>：一屏展示核心內容，避免使用者需要捲動才能看到關鍵資料</li><li><strong>留白</strong>：不要塞滿每一寸空間，適當留白讓視覺更舒適</li></ol><div class="tip custom-block"><p class="custom-block-title">儀表板 vs 報表</p><ul><li><strong>儀表板</strong>：即時/準即時，互動式，面向監控和快速決策</li><li><strong>報表</strong>：定期產生（日/週/月），靜態，面向詳細分析和存檔</li></ul><p>兩者不是替代關係，而是互補關係。儀表板發現問題，報表深入分析。</p></div><hr><h2 id="_4-工具選型-從程式庫到-bi-平台" tabindex="-1">4. 工具選型：從程式庫到 BI 平台 <a class="header-anchor" href="#_4-工具選型-從程式庫到-bi-平台" aria-label="Permalink to “4. 工具選型：從程式庫到 BI 平台”">​</a></h2><p>視覺化工具可以分為三個層次：程式級圖表庫、資料分析圖表庫、BI 平台。選擇哪個取決於需求複雜度、互動要求和團隊技術能力。</p><h3 id="_4-1-程式級圖表庫" tabindex="-1">4.1 程式級圖表庫 <a class="header-anchor" href="#_4-1-程式級圖表庫" aria-label="Permalink to “4.1 程式級圖表庫”">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>語言/平台</th><th>特點</th><th>適用場景</th></tr></thead><tbody><tr><td>ECharts</td><td>JavaScript</td><td>開箱即用，圖表類型豐富，中文文件完善</td><td>業務系統內嵌圖表</td></tr><tr><td>D3.js</td><td>JavaScript</td><td>底層靈活，可自訂任何視覺化效果</td><td>高度客製化的資料視覺化</td></tr><tr><td>Chart.js</td><td>JavaScript</td><td>輕量簡單，上手快</td><td>簡單圖表需求</td></tr><tr><td>Matplotlib</td><td>Python</td><td>科學計算標準庫，靜態圖表</td><td>資料分析、論文圖表</td></tr><tr><td>Plotly</td><td>Python/JS</td><td>互動式圖表，支援 3D</td><td>資料探索、Jupyter Notebook</td></tr></tbody></table><h3 id="_4-2-bi-平台-無程式碼-低程式碼" tabindex="-1">4.2 BI 平台（無程式碼/低程式碼） <a class="header-anchor" href="#_4-2-bi-平台-無程式碼-低程式碼" aria-label="Permalink to “4.2 BI 平台（無程式碼/低程式碼）”">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>定位</th><th>核心優勢</th><th>適用團隊</th></tr></thead><tbody><tr><td>Grafana</td><td>監控視覺化</td><td>時序資料支援好，警報整合</td><td>維運/SRE 團隊</td></tr><tr><td>Metabase</td><td>輕量 BI</td><td>開源免費，SQL 即可出圖</td><td>中小團隊快速搭建</td></tr><tr><td>Apache Superset</td><td>企業 BI</td><td>開源，支援大資料來源</td><td>有資料團隊的公司</td></tr><tr><td>Tableau</td><td>商業 BI</td><td>拖曳式操作，視覺化效果好</td><td>業務分析師</td></tr><tr><td>Power BI</td><td>商業 BI</td><td>與微軟生態整合好</td><td>使用微軟技術棧的企業</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">選型建議</p><ul><li><strong>開發者做產品內嵌圖表</strong> → ECharts（中文生態好）或 Chart.js（簡單場景）</li><li><strong>資料分析師做探索分析</strong> → Plotly + Jupyter 或 Metabase</li><li><strong>維運監控大螢幕</strong> → Grafana（事實標準）</li><li><strong>業務團隊自助分析</strong> → Metabase（開源）或 Tableau（商業）</li><li><strong>需要高度客製化</strong> → D3.js（學習曲線陡峭，但可塑性最強）</li></ul></div><hr><h2 id="_5-常見陷阱-這些圖表在騙你" tabindex="-1">5. 常見陷阱：這些圖表在騙你 <a class="header-anchor" href="#_5-常見陷阱-這些圖表在騙你" aria-label="Permalink to “5. 常見陷阱：這些圖表在騙你”">​</a></h2><p>資料視覺化是一把雙面刃：用得好能揭示真相，用得不好會製造錯覺。以下是最常見的視覺化陷阱，每個資料從業人員都應該能識別。</p><h3 id="_5-1-截斷座標軸" tabindex="-1">5.1 截斷座標軸 <a class="header-anchor" href="#_5-1-截斷座標軸" aria-label="Permalink to “5.1 截斷座標軸”">​</a></h3><p>把 Y 軸的起點從 0 改成一個較大的數字，會讓微小的差異看起來像巨大的變化。</p><table tabindex="0"><thead><tr><th>場景</th><th>真實差異</th><th>視覺感受</th></tr></thead><tbody><tr><td>Y 軸從 0 開始</td><td>A 產品 98 分，B 產品 95 分</td><td>差距很小</td></tr><tr><td>Y 軸從 90 開始</td><td>同樣的資料</td><td>A 看起來是 B 的好幾倍</td></tr></tbody></table><p><strong>什麼時候可以截斷？</strong> 當資料的絕對值很大但變化很小時（如股價從 100 到 105），截斷是合理的，但必須明確標註。</p><h3 id="_5-2-3d-圓餅圖的透視陷阱" tabindex="-1">5.2 3D 圓餅圖的透視陷阱 <a class="header-anchor" href="#_5-2-3d-圓餅圖的透視陷阱" aria-label="Permalink to “5.2 3D 圓餅圖的透視陷阱”">​</a></h3><p>3D 透視會讓靠近觀察者的扇區看起來更大。一個 25% 的扇區在 3D 視角下可能看起來像 35%。</p><p><strong>解決方案</strong>：永遠不要用 3D 圓餅圖。用普通圓餅圖或環形圖，或者乾脆用長條圖。</p><h3 id="_5-3-顏色濫用" tabindex="-1">5.3 顏色濫用 <a class="header-anchor" href="#_5-3-顏色濫用" aria-label="Permalink to “5.3 顏色濫用”">​</a></h3><table tabindex="0"><thead><tr><th>錯誤做法</th><th>正確做法</th></tr></thead><tbody><tr><td>用紅綠表示資料</td><td>用藍橙等色盲安全配色</td></tr><tr><td>每個類別用不同顏色</td><td>同一系列用同色系深淺變化</td></tr><tr><td>用顏色編碼連續資料但不加圖例</td><td>始終提供顏色圖例和數值標註</td></tr><tr><td>背景色和資料色對比度不夠</td><td>確保 WCAG AA 級對比度</td></tr></tbody></table><h3 id="_5-4-其他常見錯誤" tabindex="-1">5.4 其他常見錯誤 <a class="header-anchor" href="#_5-4-其他常見錯誤" aria-label="Permalink to “5.4 其他常見錯誤”">​</a></h3><table tabindex="0"><thead><tr><th>陷阱</th><th>問題</th><th>修復</th></tr></thead><tbody><tr><td>雙 Y 軸</td><td>兩個不相關的指標共享 X 軸，暗示因果關係</td><td>拆成兩張圖，或明確說明無因果</td></tr><tr><td>面積誤導</td><td>用圓的半徑而非面積表示數值</td><td>數值翻倍時面積翻倍，不是半徑翻倍</td></tr><tr><td>時間軸不均勻</td><td>1 月、3 月、12 月的間距一樣</td><td>按實際時間比例排列</td></tr><tr><td>過多類別</td><td>圓餅圖有 15 個扇區</td><td>超過 5 個類別就用長條圖或合併「其他」</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">視覺化的道德準則</p><p>視覺化的目的是<strong>幫助理解</strong>，不是<strong>操縱認知</strong>。每次做圖表時問自己：</p><ul><li>如果我是讀者，這張圖會不會讓我產生錯誤的結論？</li><li>我是否隱藏了不利的資料？</li><li>座標軸、比例、顏色是否公正地呈現了資料？</li></ul></div><hr><h2 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h2><p>資料視覺化是資料價值傳遞的「最後一哩」。再好的分析，如果不能被正確理解，就等於沒有分析。</p><p>回顧本章的關鍵要點：</p><ol><li><strong>選對圖表</strong>：根據資料目的（比較、趨勢、佔比、分佈、關係）選擇圖表類型</li><li><strong>設計原則</strong>：高資料墨水比、一致性、可讀性是三大核心原則</li><li><strong>儀表板佈局</strong>：概覽型、對比型、下鑽型、即時型四種模式覆蓋大部分場景</li><li><strong>工具選型</strong>：從 ECharts 到 Grafana，根據團隊能力和需求複雜度選擇</li><li><strong>避免陷阱</strong>：截斷座標軸、3D 圓餅圖、顏色濫用是最常見的誤導手段</li></ol><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to “延伸閱讀”">​</a></h2><ul><li><a href="https://www.edwardtufte.com/tufte/books_vdqi" target="_blank" rel="noreferrer">The Visual Display of Quantitative Information</a> - Edward Tufte 的視覺化經典</li><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">ECharts 官方文件</a> - 最流行的中文圖表庫</li><li><a href="https://d3js.org/" target="_blank" rel="noreferrer">D3.js</a> - 強大的底層視覺化庫</li><li><a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana</a> - 監控視覺化事實標準</li><li><a href="https://www.data-to-viz.com/" target="_blank" rel="noreferrer">From Data to Viz</a> - 圖表類型選擇決策樹</li><li><a href="https://colorbrewer2.org/" target="_blank" rel="noreferrer">ColorBrewer</a> - 色盲安全的配色方案工具</li></ul>',35))])}const f=o(n,[["render",h]]);export{u as __pageData,f as default};
